<?php foreach ($schedules as $schedule): ?><tr><td><b><?= esc($schedule['sport_name']) ?></b><small class="muted"><?= esc($schedule['category']) ?></small></td><td><?= esc($schedule['round']) ?></td><td><?= esc($schedule['location_name'] ?? '—') ?></td><td><?= esc($schedule['team_a_name'] ?? 'Open') ?> vs <?= esc($schedule['team_b_name'] ?? 'Open') ?></td><td><?= esc(date('M j, Y g:i A', strtotime($schedule['match_date']))) ?></td><td><span class="badge <?= $schedule['status'] === 'played' ? 'official' : 'neutral' ?>"><?= strtoupper(esc($schedule['status'])) ?></span></td><td><div class="row-actions"><button class="btn tiny" data-modal="schedule-edit-<?= (int) $schedule['id'] ?>"><?= ui_icon('pencil') ?><span>Edit</span></button><form method="post" action="<?= site_url('schedules/'.$schedule['id'].'/delete') ?>" data-confirm="Delete this schedule? Schedules with submitted results cannot be removed."><?= csrf_field() ?><button class="btn tiny danger"><?= ui_icon('trash') ?><span>Delete</span></button></form></div></td></tr><?php endforeach; ?>
