<?php foreach ($schedules as $schedule): ?><dialog id="schedule-edit-<?= (int) $schedule['id'] ?>"><form method="post" action="<?= site_url('schedules/'.$schedule['id'].'/update') ?>" class="modal-card wide" data-original-status="<?= esc($schedule['status'], 'attr') ?>" data-confirm-status-change="Change this schedule status? This can affect result-entry availability and the event workflow."><?= csrf_field() ?><div class="modal-head"><h2>Edit Team Schedule</h2><button type="button" data-close aria-label="Close"><?= ui_icon('x') ?></button></div><label>Sport<select name="sport_id" required><?php foreach ($sports as $sport): ?><option value="<?= (int) $sport['id'] ?>" <?= (int) $schedule['sport_id'] === (int) $sport['id'] ? 'selected' : '' ?>><?= esc($sport['name'].' · '.$sport['category']) ?></option><?php endforeach; ?></select></label><div class="form-grid"><label>Location<select name="location_id" required><?php foreach ($allLocations as $location): ?><?php if ((int) $location['is_active'] === 1 || (int) $schedule['location_id'] === (int) $location['id']): ?><option value="<?= (int) $location['id'] ?>" <?= (int) $schedule['location_id'] === (int) $location['id'] ? 'selected' : '' ?>><?= esc($location['name']) ?><?= (int) $location['is_active'] === 1 ? '' : ' (inactive)' ?></option><?php endif; ?><?php endforeach; ?></select></label><label>Status<select name="status"><option value="scheduled" <?= $schedule['status'] === 'scheduled' ? 'selected' : '' ?>>Scheduled</option><option value="played" <?= $schedule['status'] === 'played' ? 'selected' : '' ?>>Played</option><option value="cancelled" <?= $schedule['status'] === 'cancelled' ? 'selected' : '' ?>>Cancelled</option></select></label><label>Round<input name="round" maxlength="80" value="<?= esc($schedule['round']) ?>"></label><label>Match Date<input type="datetime-local" name="match_date" required value="<?= esc(date('Y-m-d\TH:i', strtotime($schedule['match_date']))) ?>"></label><label>Team A<select name="team_a_id"><option value="">Open / judged</option><?php foreach ($teams as $team): ?><option value="<?= (int) $team['id'] ?>" <?= (int) $schedule['team_a_id'] === (int) $team['id'] ? 'selected' : '' ?>><?= esc($team['name']) ?></option><?php endforeach; ?></select></label><label>Team B<select name="team_b_id"><option value="">Open / judged</option><?php foreach ($teams as $team): ?><option value="<?= (int) $team['id'] ?>" <?= (int) $schedule['team_b_id'] === (int) $team['id'] ? 'selected' : '' ?>><?= esc($team['name']) ?></option><?php endforeach; ?></select></label></div><button class="btn primary full"><?= ui_icon('save') ?><span>Save Changes</span></button></form></dialog><?php endforeach; ?>
